        raise ValueError(
            f"{field}.delta from/to must equal the previous point's at and "
            f"{field}.at"
        )
    before_rules = {
        (rule["source"], rule["id"]): rule for rule in previous["rules"]
    }
    after_rules = {(rule["source"], rule["id"]): rule for rule in rules}
    expected_entries: list[dict[str, Any]] = []
    for key in sorted(
